int cdrom_ioctl_check_media_change(struct cdrom_device_info *cdi, unsigned long arg)
{
    int ret = -ENOSYS;

    if (!cdi || !cdi->ops || !cdi->ops->check_media_change)
        return -ENOSYS;

    if (arg > CDROM_CDTEXT) {
        return -EINVAL;
    }

    if (arg == CDROM_DISC_CHECK) {
        // Assume the device can check the current disc status
        ret = cdi->ops->check_media_change(cdi, 0);
    } else if (arg == CDROM_SELECT_DISC) {
        // Assume this is a disc changer that supports selection
        struct cdrom_changer_info *info;
        info = kmalloc(sizeof(*info), GFP_KERNEL);
        if (!info)
            return -ENOMEM;

        ret = cdi->ops->get_changer_status(cdi, info);
        if (ret < 0) {
            kfree(info);
            return ret;
        }

        if (info->current_slot != info->last_accessed_slot)
            ret = 0;
        else
            ret = -ENOMEDIUM;

        kfree(info);
    }

    return ret;
}

int handle_media_change_ioctl(struct cdrom_device_info *cdi, unsigned long arg)
{
    int ret = -ENOSYS;

    if (!cdi->ops->check_media_change) {
        return -ENOSYS;
    }

    if (arg > CDROM_DISC_TRAY_OPEN && arg < CDROM_MAX_DISC) {
        ret = -EINVAL;
        return ret;
    }

    struct cdrom_changer_info *info = kmalloc(sizeof(*info), GFP_KERNEL);
    if (!info) {
        return -ENOMEM;
    }

    info->disc = arg;
    ret = cdi->ops->read_mechanism_status(cdi, info);
    if (ret < 0) {
        kfree(info);
        return ret;
    }

    ret = cdi->ops->check_media_change(cdi, info->disc);
    kfree(info);
    return ret;
}

int cdrom_ioctl_check_media_change(struct cdrom_device_info *cdi, unsigned long arg)
{
    int result;
    struct cdrom_changer_info *info;

    if (!(cdi->mask & CDC_MEDIA_CHANGE))
        return -ENOSYS;

    if (arg > CDROM_CD_IN_DRIVE)
        return -EINVAL;

    info = kmalloc(sizeof(*info), GFP_KERNEL);
    if (!info)
        return -ENOMEM;

    result = cdrom_get_changer_info(cdi, info);
    if (result < 0)
        goto out;

    if (arg == CDROM_CD_IN_DRIVE) {
        result = info->disc_present ? 0 : -ENOMEDIUM;
    } else {
        result = (info->slots[arg] != info->current_slot) ? 0 : -ENOMEDIUM;
    }

out:
    kfree(info);
    return result;
}

int cdrom_ioctl_check_media_change(struct cdrom_device_info *cdi, unsigned long arg)
{
    int result = -ENOSYS;

    if (!cdi || !cdi->ops || !cdi->ops->check_media_change)
        return -ENOSYS;

    if (arg > CDROM_DISC_SELECTABLE)
        return -EINVAL;

    struct cdrom_changer_info *info = kmalloc(sizeof(*info), GFP_KERNEL);
    if (!info)
        return -ENOMEM;

    result = cdi->ops->check_media_change(cdi, info);
    if (result < 0)
        goto out;

    if (arg == CDROM_CURRENT_DISC) {
        result = info->current_disc;
    } else if (arg <= CDROM_DISC_SELECTABLE) {
        result = (info->discs[arg].present) ? 0 : -ENOMEDIUM;
    } else {
        result = -EINVAL;
    }

out:
    kfree(info);
    return result;
}

#include <linux/cdrom.h>
#include <linux/errno.h>
#include <linux/slab.h>

int handle_ioctl_media_change(struct cdrom_device_info *cdi, unsigned long arg)
{
    if (!(cdi->mask & CDC_MEDIA_CHANGED))
        return -ENOSYS;

    if (arg > CDROM_MAX_DISC)
        return -EINVAL;

    struct cdrom_changer_info *info = kmalloc(sizeof(*info), GFP_KERNEL);
    if (!info)
        return -ENOMEM;

    int ret = cdi->ops->drive_status(cdi, CDSL_CURRENT, info);
    if (ret)
        goto out;

    ret = (info->discs[arg].present) ? -1 : 0;

out:
    kfree(info);
    return ret;
}
